actor Items {
    var list: [Int] = []
    func add(_ n: Int) { list.append(n) }
}
let items = Items(); await items.add(1)
print(await items.list)  // no data race

struct Point: Sendable { let x, y: Int }
let p = Point(x: 1, y: 2)
let task = Task { p.x + p.y }
print(await task.value)

struct Note: Sendable { let text: String }
actor Inbox { func put(_ n: Note) {} }
let box = Inbox()
await box.put(Note(text: "hi"))  // crosses
print("crossed")

